 sc=(tags.entity?4:0)+((/^D4/.test(d)||/^D4/.test(String(m.depth||'')))?1:0)+(has(t,/\uc778\ubb3c|\ub2e8\uccb4|\uc870\uc9c1|\ud65c\ub3d9/)?2:0);add(arr,'entity_activity_link',sc,[tags.entity?'entity-question':null]);
 sc=(/^D4/.test(String(m.depth||''))?5:0)+(/^D4/.test(d)?3:0)+(has(m.skill,/\uad6c\ubcc4/)?3:0);add(arr,'concept_boundary',sc,[/^D4/.test(String(m.depth||''))?'D4-metacog':null,has(m.skill,/\uad6c\ubcc4/)?'distinction':null]);
 sc=(/^D3/.test(String(m.depth||''))?5:0)+(/^D3/.test(d)?4:0)+(tags.causal?2:0)+(has(t,/\uc6d0\uc778|\uacb0\uacfc|\ubc30\uacbd|\uc758\uc758/)?1:0);add(arr,'causal_chain',sc,[tags.causal?'causal-question':null]);
 if(memorySuccess(s,cat)&&((/^D2/.test(String(m.depth||''))||/^D2/.test(d))||tags.term)){sc=3+(tags.term?1:0)+3;add(arr,'surface_term_memory',sc,['keyword-recall-success'])}
