function collect(storage,now){storage=storageMap(storage);now=now||Date.now();const ev=[],rem=[];for(let day=1;day<=6;day++){const key=storage[String(day)];if(!key)continue;const s=readState(key);for(const a of (s.attempts||[])){if(a&&a.correct===false){for(const c of classifyAttempt(day,a,s)){const cat=catFor(day,a.problemId);ev.push({patternId:c.patternId,score:c.score,day,problemId:a.problemId,uid:'d'+day+'-'+a.problemId,at:Number(a.at||0),branchLabel:cat&&cat.branchLabel||'',conceptTitle:cat&&cat.conceptTitle||'',reasons:c.reasons})}}}for(const r of (s.patternRemediationLog||[])){if(r&&r.patternId)rem.push({...r,day:Number(r.day||day)})}}return {ev,rem,now}}
